package exam; public class Monitoring { public enum Status {READY,CLEARED,CANCELLED} public final String id,detail; private Status status; public Monitoring(String id,String detail,Status status){this.id=id;this.detail=detail;this.status=status;} public Status status(){return status;} public void clear(){if(status!=Status.READY)throw new IllegalStateException("Illegal transition "+status);status=Status.CLEARED;} public void cancel(){if(status!=Status.CLEARED)throw new IllegalStateException("Illegal transition "+status);status=Status.CANCELLED;}}
